const TEMPLATE_LAYOUTS=new Set(['classic','premium','dark','band','industrial','minimal','modern','editorial','executive','split','grid','soft']);
const TEMPLATE_ID_RE=/^[a-z0-9][a-z0-9-]{1,63}$/;
const TEMPLATE_COLOR_RE=/^#[0-9a-fA-F]{6}$/;
function builtinTemplate(id){return TEMPLATE_LIBRARY.find(t=>t.id===String(id));}
function installedTemplates(){return Array.isArray(state?._meta?.installedTemplates)?state._meta.installedTemplates:[]}
function allTemplates(){return [...TEMPLATE_LIBRARY,...installedTemplates().filter(t=>!builtinTemplate(t.id))]}
function normalizeTemplate(t){
 if(!t||typeof t!=='object'||Array.isArray(t))return null;
 const id=String(t.id||'').trim().toLowerCase();
 if(!TEMPLATE_ID_RE.test(id)||!TEMPLATE_COLOR_RE.test(String(t.accent||''))||!TEMPLATE_COLOR_RE.test(String(t.soft||''))||!TEMPLATE_COLOR_RE.test(String(t.ink||'')))return null;
 const layout=TEMPLATE_LAYOUTS.has(String(t.layout||''))?String(t.layout):'classic';
 const name=String(t.name||'Plantilla SK House').trim().slice(0,80);
 const desc=String(t.desc||'Diseño personalizado').trim().slice(0,160);
 if(!name)return null;
 const updatedAt=String(t.updatedAt||'');
 return {id,name,desc,accent:String(t.accent).toLowerCase(),soft:String(t.soft).toLowerCase(),ink:String(t.ink).toLowerCase(),layout,...(updatedAt&&Number.isFinite(Date.parse(updatedAt))?{updatedAt}:{})};
}
function normalizeTemplatePackage(x){
 if(!x||typeof x!=='object'||Array.isArray(x)||x.type!=='sk-house-template'||!x.template)return null;
 const v=String(x.version||'');
 if(!/^3(?:\.0|\.1)$/.test(v))return null;
 return normalizeTemplate(x.template);
}
function currentTemplateId(){return String(state?._meta?.templateId||TEMPLATE_DEFAULT)}
function currentTemplate(){return allTemplates().find(t=>t.id===currentTemplateId())||TEMPLATE_LIBRARY[0]}
function applyTemplate(){const t=currentTemplate();document.body.dataset.template=t.id;document.documentElement.style.setProperty('--template-accent',t.accent);document.documentElement.style.setProperty('--template-soft',t.soft);document.documentElement.style.setProperty('--template-ink',t.ink);document.documentElement.style.setProperty('--template-layout',t.layout)}
function selectTemplate(id){const t=allTemplates().find(x=>x.id===String(id));if(!t)return;state._meta.templateId=t.id;state._meta.templateUpdatedAt=new Date().toISOString();normalizeStateData();save();applyTemplate();render();toast('Plantilla aplicada')}
function downloadTemplate(id){const t=allTemplates().find(x=>x.id===String(id));if(!t)return;const payload={type:'sk-house-template',version:TEMPLATE_VERSION,template:{id:t.id,name:t.name,desc:t.desc,accent:t.accent,soft:t.soft,ink:t.ink,layout:t.layout,...(t.updatedAt?{updatedAt:t.updatedAt}:{})}};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='SK_House_Plantilla_'+t.id+'.skhctemplate';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function installTemplate(file){
 if(!file)return;
 if(file.size>TEMPLATE_MAX_FILE_BYTES){toast('La plantilla supera el límite de 100 KB');return;}
 const r=new FileReader();
 r.onload=()=>{
 try{
 const x=JSON.parse(r.result);
 const t=normalizeTemplatePackage(x);
 if(!t)throw new Error('INVALID_TEMPLATE');
 const builtin=builtinTemplate(t.id);
 if(builtin){selectTemplate(builtin.id);toast('Plantilla integrada seleccionada');return;}
 state._meta.installedTemplates=installedTemplates().filter(v=>v.id!==t.id);
 state._meta.installedTemplates.push({...t,updatedAt:new Date().toISOString()});
 if(state._meta.installedTemplates.length>100)state._meta.installedTemplates=state._meta.installedTemplates.slice(-100);
 state._meta.templateId=t.id;
 state._meta.templateUpdatedAt=new Date().toISOString();
 normalizeStateData();save();applyTemplate();render();toast('Plantilla instalada y aplicada');
 }catch(e){console.warn('Template install:',e);toast('Archivo de plantilla no válido o incompatible')}
 };
 r.onerror=()=>toast('No se pudo leer el archivo de plantilla.');
 r.readAsText(file);
}
function removeInstalledTemplate(id){
 const t=installedTemplates().find(x=>x.id===String(id));if(!t)return;
 state._meta.installedTemplates=installedTemplates().filter(x=>x.id!==t.id);
 if(state._meta.templateId===t.id)state._meta.templateId=TEMPLATE_DEFAULT;
 state._meta.templateUpdatedAt=new Date().toISOString();normalizeStateData();save();applyTemplate();render();toast('Plantilla eliminada');
}
function templates(c){
 const active=currentTemplateId();
 const installed=installedTemplates();
 c.innerHTML=`<div class="section templates-page"><div class="templates-head"><div><h1>Plantillas</h1><p class="muted">Cambia únicamente el aspecto visual. Tus datos, folios, bancos, IVA, imágenes y logotipo permanecen intactos.</p></div><label class="btn primary template-install">＋ Instalar plantilla<input type="file" accept=".skhctemplate,.json,application/json" hidden onchange="installTemplate(this.files[0]);this.value=''" ></label></div><div class="template-notice"><span class="emoji"></span> <strong>Seguro para tus datos:</strong> las plantillas solo guardan el diseño, nunca tus clientes ni documentos. Puedes instalar archivos externos sin sobrescribir tus datos.</div><div class="template-grid">${allTemplates().map(t=>`<article class="template-card ${t.id===active?'selected':''}" style="--card-accent:${t.accent};--card-soft:${t.soft};--card-ink:${t.ink}"><div class="template-preview layout-${esc(t.layout||'classic')}"><div class="mini-head"><span class="mini-logo">SK</span><span></span></div><div class="mini-title">COTIZACIÓN</div><div class="mini-lines"><i></i><i></i><i></i></div><div class="mini-table"><b></b><b></b><b></b><b></b></div><div class="mini-total"></div></div><div class="template-info"><div><h3>${esc(t.name)}</h3><p>${esc(t.desc)}</p></div>${t.id===active?'<span class="template-active">ACTIVA</span>':''}</div><div class="template-actions"><button class="btn ${t.id===active?'outline':'primary'}" onclick="selectTemplate('${esc(t.id)}')">${t.id===active?'Usando esta':'Usar plantilla'}</button><button class="btn outline" onclick="downloadTemplate('${esc(t.id)}')">⬇ Descargar</button>${installed.some(x=>x.id===t.id)?`<button class="btn outline danger" onclick="removeInstalledTemplate('${esc(t.id)}')">Eliminar</button>`:''}</div></article>`).join('')}</div></div>`
}

