const KEY='skhc_v1';
const DEFAULT_SETTINGS={company:'SK House Construction',name:'',phone:'',email:'',address:'',rfc:'',bank:'',holder:'',account:'',bank2:'',holder2:'',account2:'',card:'',secondaryBankEnabled:false,card2:'',iva:16,notes:'Gracias por su preferencia.'};
function normalizeIva(v){
 const n=Number(String(v??'').replace(',','.'));
 return Number.isFinite(n)&&n>=0&&n<=100?n:16;
}
function normalizeNonNegative(v,fallback=0){
 const n=num(v); return n>=0?n:fallback;
}
function cleanImageCaption(value){
 const text=String(value??'').trim();
 if(!text)return '';
 // Never filter normal user descriptions. Only remove the exact legacy
 // status message that was accidentally stored as an image caption.
 const legacyArtifact=/^Actualic[eé] el Service Worker y su cach[eé] a la versi[oó]n estable\s*\.?$/i;
 return legacyArtifact.test(text) ? '' : text;
}

function normalizeImageEntry(x){
 if(!x)return null;
 if(typeof x==='string')return {data:x,text:'',scale:1,captionSource:'legacy'};
 return {data:String(x.data||x.image||''),text:cleanImageCaption(x.text??x.imageText??''),scale:Math.max(.5,Math.min(2.5,Number(x.scale||x.imageScale||1)||1)),captionSource:x.captionSource==='user'?'user':'legacy'};
}
function normalizeDocument(x){
 const d=(x&&typeof x==='object')?x:{};
 d.id=String(d.id||makeId('doc'));
 d.type=d.type==='note'?'note':'quote';
 d.folio=String(d.folio||'');
 d.date=d.date||d.dateStart||today();
 d.dateStart=d.dateStart||d.date||today();
 d.dateEnd=d.dateEnd||addDays(d.dateStart,d.type==='quote'?15:0);
 d.status=String(d.status||'Pendiente');
 d.company={...DEFAULT_SETTINGS,...(d.company&&typeof d.company==='object'?d.company:{})};
 d.company.iva=normalizeIva(d.company.iva);
 d.client={name:'',phone:'',email:'',rfc:'',address:'',...(d.client&&typeof d.client==='object'?d.client:{})};
 d.items=Array.isArray(d.items)?d.items:[];
 d.items=d.items.map(it=>({qty:normalizeNonNegative(it?.qty,0),desc:String(it?.desc??it?.name??''),price:normalizeNonNegative(it?.price??it?.unitPrice,0),images:Array.isArray(it?.images)?it.images.map(normalizeImageEntry).filter(Boolean):[]}));
 if(!d.items.length)d.items=[{qty:1,desc:'',price:0,images:[]}];
 d.discount=normalizeNonNegative(d.discount,0);
 d.applyIva=d.applyIva!==false;
 d.notes=String(d.notes??d.company.notes??'');
 // Keep persisted totals consistent with the current document contents.
 // The calculated value is authoritative; this also repairs older backups
 // whose stored total may be stale.
 const calculatedTotal=(()=>{
 const sub=d.items.reduce((sum,it)=>sum+normalizeNonNegative(it.qty,0)*normalizeNonNegative(it.price,0),0);
 const discount=Math.max(0,num(d.discount));
 const taxable=Math.max(0,sub-discount);
 const rate=normalizeIva(d.company?.iva ?? 16);
 return taxable+(d.applyIva===false?0:taxable*rate/100);
 })();
 d.total=Number.isFinite(calculatedTotal)?calculatedTotal:0;
 if(d.updatedAt && !Number.isFinite(Date.parse(d.updatedAt))) delete d.updatedAt;
 return d;
}
function normalizeToolList(x){
 const d=(x&&typeof x==='object')?x:{};
 d.id=String(d.id||makeId('tool'));
 d.name=String(d.name||'Lista de herramientas');
 d.date=d.date||today();
 d.notes=String(d.notes??'');
 d.company={...DEFAULT_SETTINGS,...(d.company&&typeof d.company==='object'?d.company:{})};
 d.clientId=String(d.clientId||'');
 d.email=String(d.email||'');
 d.phone=String(d.phone||'');
 d.items=Array.isArray(d.items)?d.items:[];
 d.items=d.items.map(it=>({qty:normalizeNonNegative(it?.qty,1),name:String(it?.name??''),unit:String(it?.unit??'pz'),obs:String(it?.obs??''),image:String(it?.image??it?.data??''),imageText:cleanImageCaption(it?.imageText??it?.text??''),imageScale:Math.max(.5,Math.min(2.5,Number(it?.imageScale||it?.scale||1)||1))}));
 if(!d.items.length)d.items=[{qty:1,name:'',unit:'pz',obs:'',image:'',imageText:'',imageScale:1}];
 if(d.updatedAt && !Number.isFinite(Date.parse(d.updatedAt))) delete d.updatedAt;
 return d;
}
function normalizeStateData(){
 state.settings={...DEFAULT_SETTINGS,...(state.settings&&typeof state.settings==='object'?state.settings:{})};
 state.settings.iva=normalizeIva(state.settings.iva);
 state.settings.secondaryBankEnabled = state.settings.secondaryBankEnabled===true || state.settings.secondaryBankEnabled===1 || state.settings.secondaryBankEnabled==='1' || Boolean(state.settings.bank2||state.settings.holder2||state.settings.account2||state.settings.card2);
 state.clients=Array.isArray(state.clients)?state.clients.filter(x=>x&&typeof x==='object').map(x=>({id:String(x.id||makeId('client')),name:String(x.name??''),phone:String(x.phone??''),email:String(x.email??''),rfc:String(x.rfc??''),address:String(x.address??''),...(x.updatedAt?{updatedAt:x.updatedAt}:{})})):[];
 state.products=Array.isArray(state.products)?state.products.filter(x=>x&&typeof x==='object').map(x=>({...x,id:String(x.id||makeId('product')),name:String(x.name??''),description:String(x.description??''),price:normalizeNonNegative(x.price??x.precio??0,0),unit:String(x.unit??'pz'),...(x.updatedAt?{updatedAt:x.updatedAt}:{})})):[];
 state.documents=Array.isArray(state.documents)?state.documents.map(normalizeDocument):[];
 state.toolLists=Array.isArray(state.toolLists)?state.toolLists.map(normalizeToolList):[];
 state._meta=(state._meta&&typeof state._meta==='object')?state._meta:{};
 const rawInstalled=Array.isArray(state._meta.installedTemplates)?state._meta.installedTemplates:[];
 state._meta.installedTemplates=[];
 const seen=new Set();
 for(const raw of rawInstalled){const t=normalizeTemplate(raw);if(!t||builtinTemplate(t.id)||seen.has(t.id))continue;seen.add(t.id);state._meta.installedTemplates.push(t);if(state._meta.installedTemplates.length>=100)break;}
 state._meta.templateId=String(state._meta.templateId||TEMPLATE_DEFAULT);
 if(!allTemplates().some(t=>t.id===state._meta.templateId))state._meta.templateId=TEMPLATE_DEFAULT;
 state._meta.deleted=(state._meta.deleted&&typeof state._meta.deleted==='object')?state._meta.deleted:{};
 for(const k of ['clients','products','documents','toolLists'])state._meta.deleted[k]=Array.isArray(state._meta.deleted[k])?state._meta.deleted[k].map(String).filter(Boolean):[];
 state._meta.localRevision=Number.isFinite(Number(state._meta.localRevision))?Number(state._meta.localRevision):0;
 state._meta.usedFolios=(state._meta.usedFolios&&typeof state._meta.usedFolios==='object')?state._meta.usedFolios:{};
 for(const k of ['quote','note'])state._meta.usedFolios[k]=Array.isArray(state._meta.usedFolios[k])?state._meta.usedFolios[k].map(String).filter(Boolean):[];
 for(const d of state.documents){if(d?.folio){const k=d.type==='note'?'note':'quote';if(!state._meta.usedFolios[k].includes(String(d.folio)))state._meta.usedFolios[k].push(String(d.folio));}}
 if(!Object.prototype.hasOwnProperty.call(state,'editing'))state.editing=null;
 if(!Object.prototype.hasOwnProperty.call(state,'view'))state.view='dashboard';
 return state;
}
function validBackup(x){
 if(!x||typeof x!=='object'||Array.isArray(x)||x.version===undefined)return false;
 if(!x.settings||typeof x.settings!=='object'||Array.isArray(x.settings))return false;
 const names=['clients','products','documents','toolLists'];
 if(!names.every(k=>Array.isArray(x[k])))return false;
 for(const k of names){
 if(x[k].length>100000)return false;
 if(!x[k].every(v=>v&&typeof v==='object'&&!Array.isArray(v)))return false;
 }
 return true;
}
let __initialState=null;
try{__initialState=JSON.parse(localStorage.getItem(KEY)||'null');}catch(e){console.warn('Datos locales dañados; se iniciará con una estructura limpia.',e);}
const state=__initialState&&typeof __initialState==='object'&&!Array.isArray(__initialState)?__initialState:{toolLists:[],settings:{...DEFAULT_SETTINGS},clients:[],products:[],documents:[],editing:null,_meta:{}};
state._meta=state._meta&&typeof state._meta==='object'?state._meta:{};
if(state._meta.templateId==='carbón')state._meta.templateId='carbon';
state._meta.templateId=String(state._meta.templateId||TEMPLATE_DEFAULT);
normalizeStateData();
let cloudSyncReady=false;
let cloudSaveQueue=Promise.resolve();
state._meta.cloudSyncPending=Boolean(state._meta.cloudSyncPending);
function touchRecord(record){if(record&&typeof record==='object')record.updatedAt=new Date().toISOString();state._meta.updatedAt=new Date().toISOString();state._meta.localRevision=(Number(state._meta.localRevision)||0)+1;}
function saveLocal(){
 try{
 localStorage.setItem(KEY,JSON.stringify(state));
 return true;
 }catch(e){
 console.error('Local save:',e);
 if(e?.name==='QuotaExceededError'||/quota/i.test(String(e?.message||''))) toast('No hay suficiente espacio del navegador para guardar los datos. Elimina imágenes antiguas o descarga un respaldo.');
 else toast('No se pudieron guardar los datos localmente.');
 return false;
 }
}
function applyCloudState(payload){
 if(!payload||typeof payload!=='object')return;
 const merged=mergeCloudState(state,payload);
 Object.keys(state).forEach(k=>delete state[k]);
 Object.assign(state,merged);
 state.editing=null;
 normalizeStateData();
}
async function persistCloud(){
 if(!window.SKCloud||!cloudSyncReady)return {skipped:true};
 try{
 const revision=Number(state._meta?.localRevision)||0;
 const result=await window.SKCloud.saveState(state);
 if(result?.payload){
 if((Number(state._meta?.localRevision)||0)===revision){
 applyCloudState(result.payload);
 state._meta.cloudSyncPending=false;
 saveLocal();
 }else{
 state._meta.cloudSyncPending=true;
 saveLocal();
 }
 }
 if(result?.updatedAt)state._meta.cloudUpdatedAt=result.updatedAt;
 return result;
 }catch(e){
 state._meta.cloudSyncPending=true;
 saveLocal();
 console.warn('Cloud save:',e);
 throw e;
 }
}
function save(){
 saveLocal();
 if(window.SKCloud&&cloudSyncReady){
 state._meta.cloudSyncPending=true;
 saveLocal();
 cloudSaveQueue=cloudSaveQueue.then(()=>persistCloud()).catch(e=>{
 console.warn('Cloud save:',e);
 state._meta.cloudSyncPending=true;
 saveLocal();
 toast('Cambios guardados en este dispositivo, pero no se pudieron sincronizar con la nube.');
 return {error:e};
 });
 }
 return cloudSaveQueue;
}
function mergeRecords(local,remote){
 const lm=Array.isArray(local)?local:[],rm=Array.isArray(remote)?remote:[],map=new Map();
 for(const r of lm)if(r&&typeof r==='object')map.set(String(r.id||makeId('record')),r);
 for(const r of rm){if(!r||typeof r!=='object')continue;const id=String(r.id||makeId('record')),cur=map.get(id);if(!cur){map.set(id,r);continue;}const lt=Date.parse(cur.updatedAt||'')||0,rt=Date.parse(r.updatedAt||'')||0;if(rt>=lt)map.set(id,r);}
 return [...map.values()];
}
function mergeCloudState(local,cloud){
 const merged={...local};
 const lset=Date.parse(local._meta?.settingsUpdatedAt||'')||0;const rset=Date.parse(cloud._meta?.settingsUpdatedAt||'')||0;
 merged.settings={...DEFAULT_SETTINGS,...((rset>=lset&&cloud.settings)?cloud.settings:(local.settings||{}))};
 const ld=local._meta?.deleted||{},rd=cloud._meta?.deleted||{};
 merged._meta={...(cloud._meta||{}),...(local._meta||{}),deleted:{},usedFolios:{}};
 const templateMap=new Map();
 const putTemplates=(arr)=>{for(const raw of (Array.isArray(arr)?arr:[])){const t=normalizeTemplate(raw);if(!t||builtinTemplate(t.id))continue;const ts=Date.parse(t.updatedAt||'')||0;const cur=templateMap.get(t.id);const cts=Date.parse(cur?.updatedAt||'')||0;if(!cur||ts>=cts)templateMap.set(t.id,t);}};
 putTemplates(cloud._meta?.installedTemplates);
 putTemplates(local._meta?.installedTemplates);
 merged._meta.installedTemplates=[...templateMap.values()].slice(-100);
 const ltpl=Date.parse(local._meta?.templateUpdatedAt||'')||0, rtpl=Date.parse(cloud._meta?.templateUpdatedAt||'')||0;
 merged._meta.templateId=rtpl>ltpl?String(cloud._meta?.templateId||TEMPLATE_DEFAULT):String(local._meta?.templateId||TEMPLATE_DEFAULT);
 merged._meta.templateUpdatedAt=rtpl>ltpl?(cloud._meta?.templateUpdatedAt||''):(local._meta?.templateUpdatedAt||'');
 if(![...TEMPLATE_LIBRARY,...merged._meta.installedTemplates].some(t=>t.id===merged._meta.templateId))merged._meta.templateId=TEMPLATE_DEFAULT;
 for(const k of ['quote','note']){
 const lu=Array.isArray(local._meta?.usedFolios?.[k])?local._meta.usedFolios[k]:[];
 const ru=Array.isArray(cloud._meta?.usedFolios?.[k])?cloud._meta.usedFolios[k]:[];
 merged._meta.usedFolios[k]=[...new Set([...lu,...ru].map(String).filter(Boolean))];
 }
 for(const k of ['clients','products','documents','toolLists']){
 const tomb=new Set([...(Array.isArray(ld[k])?ld[k]:[]).map(String),...(Array.isArray(rd[k])?rd[k]:[]).map(String)]);
 merged._meta.deleted[k]=[...tomb];
 merged[k]=mergeRecords(local[k],cloud[k]).filter(r=>!tomb.has(String(r.id||'')));
 }
 merged._meta.updatedAt=new Date().toISOString();
 return merged;
}
function cloudPayloadFingerprint(p){
 try{
 const x=p&&typeof p==='object'?p:{};
 return JSON.stringify({
 version:x.version||APP_VERSION,
 settings:x.settings||{},
 clients:x.clients||[],
 products:x.products||[],
 documents:x.documents||[],
 toolLists:x.toolLists||[],
 meta:{deleted:x.meta?.deleted||{},usedFolios:x.meta?.usedFolios||{},settingsUpdatedAt:x.meta?.settingsUpdatedAt||'',templateId:x.meta?.templateId||TEMPLATE_DEFAULT,templateUpdatedAt:x.meta?.templateUpdatedAt||'',installedTemplates:x.meta?.installedTemplates||[]}
 });
 }catch(e){return '';}
}
function hasLocalBusinessData(){
 const s=state.settings||{};
 const meaningful=['name','phone','email','address','rfc','bank','holder','account','card','bank2','holder2','account2','card2'];
 return Boolean(
 (state.clients||[]).length ||
 (state.products||[]).length ||
 (state.documents||[]).length ||
 (state.toolLists||[]).length ||
 meaningful.some(k=>String(s[k]??'').trim())
 );
}
function resetLocalState(){
 const fresh={toolLists:[],settings:{...DEFAULT_SETTINGS},clients:[],products:[],documents:[],editing:null,view:'dashboard',_meta:{}};
 Object.keys(state).forEach(k=>delete state[k]);
 Object.assign(state,fresh);
 normalizeStateData();
}
async function syncCloudIntoState(){
 try{
 const cloud=window.SKCloud?await window.SKCloud.loadState():null;
 const user=window.SKCloud?await window.SKCloud.session():null;
 if(!user) {cloudSyncReady=false;updateCloudStatus();return;}
 const owner=String(state._meta?.ownerUserId||'');
 const sameOwner=!owner || owner===String(user.user.id);
 if(!sameOwner){
 resetLocalState();
 }
 const localBefore=buildCloudComparable(state);
 if(cloud?.payload){
 const merged=mergeCloudState(state,cloud.payload);
 const mergedFingerprint=cloudPayloadFingerprint({version:APP_VERSION,settings:merged.settings,clients:merged.clients,products:merged.products,documents:merged.documents,toolLists:merged.toolLists,meta:merged._meta});
 const cloudFingerprint=cloudPayloadFingerprint(cloud.payload);
 Object.keys(state).forEach(k=>delete state[k]);
 Object.assign(state,merged);
 state.editing=null;
 state._meta.ownerUserId=String(user.user.id);
 state._meta.cloudUpdatedAt=cloud.updatedAt||'';
 normalizeStateData();
 saveLocal();
 cloudSyncReady=true;
 if(mergedFingerprint!==cloudFingerprint || (!sameOwner && owner)){
 const saved=await window.SKCloud.saveState(state,cloud.updatedAt||null);
 if(saved?.payload)applyCloudState(saved.payload);
 if(saved?.updatedAt)state._meta.cloudUpdatedAt=saved.updatedAt;
 state._meta.ownerUserId=String(user.user.id); state._meta.cloudSyncPending=false; saveLocal();
 } else if(sameOwner && owner && localBefore!==cloudFingerprint && hasLocalBusinessData()){
 const saved=await window.SKCloud.saveState(state,cloud.updatedAt||null);
 if(saved?.payload)applyCloudState(saved.payload);
 if(saved?.updatedAt)state._meta.cloudUpdatedAt=saved.updatedAt;
 state._meta.ownerUserId=String(user.user.id); state._meta.cloudSyncPending=false; saveLocal();
 }
 toast('Datos sincronizados con la nube');
 } else {
 cloudSyncReady=true;
 state._meta.ownerUserId=String(user.user.id);
 const saved=await window.SKCloud.saveState(state,null);
 if(saved?.payload)applyCloudState(saved.payload);
 if(saved?.updatedAt)state._meta.cloudUpdatedAt=saved.updatedAt;
 state._meta.cloudSyncPending=false; saveLocal();
 toast('Datos locales sincronizados con la nube');
 }
 render(); updateCloudStatus();
 }catch(e){
 cloudSyncReady=false;console.error(e);
 toast('No se pudo sincronizar con la nube. Tus datos locales permanecen intactos.');
 updateCloudStatus();
 }
}
function buildCloudComparable(s){
 try{
 return cloudPayloadFingerprint({version:APP_VERSION,settings:s.settings,clients:s.clients,products:s.products,documents:s.documents,toolLists:s.toolLists,meta:s._meta});
 }catch(e){return '';}
}
async function backgroundCloudSync(){
 if(!window.SKCloud||!cloudSyncReady)return;
 try{
 const user=await window.SKCloud.session(); if(!user)return;
 const cloud=await window.SKCloud.loadState(); if(!cloud?.payload)return;
 if(String(state._meta?.ownerUserId||'')!==String(user.user.id)){await syncCloudIntoState();return;}
 const merged=mergeCloudState(state,cloud.payload);
 const localFp=buildCloudComparable(state), mergedFp=buildCloudComparable(merged), cloudFp=cloudPayloadFingerprint(cloud.payload);
 const changed=mergedFp!==localFp;
 if(changed){
 Object.keys(state).forEach(k=>delete state[k]);Object.assign(state,merged);
 state._meta.ownerUserId=String(user.user.id);state._meta.cloudUpdatedAt=cloud.updatedAt||'';
 normalizeStateData();saveLocal();render();
 }
 if(mergedFp!==cloudFp){
 const saved=await window.SKCloud.saveState(state,cloud.updatedAt||null);
 if(saved?.payload)applyCloudState(saved.payload);
 if(saved?.updatedAt)state._meta.cloudUpdatedAt=saved.updatedAt;
 state._meta.ownerUserId=String(user.user.id);
 state._meta.cloudSyncPending=false;
 saveLocal();
 }else if(state._meta?.cloudSyncPending){
 // The cloud version already represents the merged state; there is nothing left to upload.
 state._meta.cloudSyncPending=false;
 saveLocal();
 }
 }catch(e){console.warn('Background cloud sync:',e);}
}
function cloudStatusText(){return window.SKCloud?.configured()?'Configuración de nube guardada':'Nube no configurada'}
async function updateCloudStatus(){
 const el=document.getElementById('cloudStatus');if(!el)return;
 el.innerHTML='<span class="muted">Comprobando conexión…</span>';
 try{
 const s=window.SKCloud?await window.SKCloud.session():null;
 if(s){
 const email=String(s.user?.email||window.SKCloud?.getLastLoginEmail?.()||'').trim();
 const login=document.getElementById('cloud_email');
 if(login && email)login.value=email;
 el.innerHTML=`<span class="cloud-ok">● Conectado: ${esc(email||'usuario')}</span>`;
 }else{
 el.innerHTML=`<span class="muted">○ ${esc(cloudStatusText())}</span>`;
 }
 }catch(e){
 console.error('Cloud status:',e);
 const msg=String(e?.message||'');
 el.innerHTML=`<span class="muted">○ ${msg==='CLOUD_SESSION_TIMEOUT'?'Nube no responde; tus datos locales están disponibles.':'Nube no disponible'}</span>`;
 }
}
async function cloudConfigure(){const url=document.getElementById('cloud_url').value.trim(),key=document.getElementById('cloud_key').value.trim();if(!url||!key)return toast('Escribe la URL y la clave pública de Supabase');window.SKCloud.setConfig(url,key);await updateCloudStatus();toast('Configuración de nube guardada')}
async function cloudLogin(){try{const email=document.getElementById('cloud_email').value.trim(),pass=document.getElementById('cloud_pass').value;if(!email||!pass)return toast('Escribe correo y contraseña');const r=await window.SKCloud.signIn(email,pass);if(r.error)throw r.error;localStorage.setItem('skhc_last_login_email_v1',email);await syncCloudIntoState();clearInterval(window.SKCloudSyncTimer);window.SKCloudSyncTimer=setInterval(backgroundCloudSync,30000);toast('Conectado a la nube')}catch(e){console.error(e);toast(e.message||'No se pudo iniciar sesión')}}
async function cloudSignup(){try{const email=document.getElementById('cloud_email').value.trim(),pass=document.getElementById('cloud_pass').value;if(!email||pass.length<6)return toast('Usa un correo y una contraseña de al menos 6 caracteres');const r=await window.SKCloud.signUp(email,pass);if(r.error)throw r.error; if(r.data.session){await syncCloudIntoState();clearInterval(window.SKCloudSyncTimer);window.SKCloudSyncTimer=setInterval(backgroundCloudSync,30000);toast('Cuenta creada y conectada')}else toast('Cuenta creada. Revisa tu correo para confirmar y después inicia sesión.')}catch(e){console.error(e);toast(e.message||'No se pudo crear la cuenta')}}
async function cloudLogout(){
 try{
 if(!window.SKCloud)return;
 const pending=Boolean(state._meta?.cloudSyncPending);
 if(pending){
 toast('Sincronizando cambios pendientes antes de cerrar sesión…');
 await cloudSaveQueue;
 if(state._meta?.cloudSyncPending){
 cloudSyncReady=true;
 await persistCloud();
 }
 if(state._meta?.cloudSyncPending){
 toast('No se puede cerrar sesión todavía: hay cambios pendientes de sincronizar.');
 return;
 }
 }
 clearInterval(window.SKCloudSyncTimer);window.SKCloudSyncTimer=null;
 cloudSyncReady=false;
 await window.SKCloud.signOut();
 resetLocalState();
 state._meta.cloudSyncPending=false;
 saveLocal();
 render();await updateCloudStatus();toast('Sesión cerrada. Los datos permanecen en la nube y se cargarán al volver a iniciar sesión.');
 }catch(e){
 console.error('Cloud logout:',e);
 toast('No se cerró la sesión porque no fue posible confirmar la sincronización de los cambios.');
 }
}
function price(x){const n=Number(x?.price??x?.precio??x?.unitPrice??x?.precioVenta);return Number.isFinite(n)?n:null}
function money(n){return new Intl.NumberFormat('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:true}).format(Number(n)||0)}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function addDays(dateStr,days){const d=new Date(`${dateStr}T12:00:00`);d.setDate(d.getDate()+Number(days||0));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function documentDates(type,start){const inicio=start||today();return {dateStart:inicio,dateEnd:type==='quote'?addDays(inicio,15):inicio}}
function makeId(prefix='id'){try{if(crypto?.randomUUID)return crypto.randomUUID()}catch(e){} return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,9)}`}
function folio(type){
 const p=type==='quote'?'COT':'NV';
 const year=new Date().getFullYear();
 const key=type==='note'?'note':'quote';
 const used=new Set([...(state._meta?.usedFolios?.[key]||[]).map(String),...(state.documents||[]).filter(x=>x.type===type).map(x=>String(x.folio||''))]);
 let n=1;
 while(used.has(`${p}-${year}-${String(n).padStart(4,'0')}`))n++;
 return `${p}-${year}-${String(n).padStart(4,'0')}`;
}
function registerFolio(type,value){
 if(!value)return;
 const key=type==='note'?'note':'quote';
 state._meta.usedFolios=state._meta.usedFolios||{};
 state._meta.usedFolios[key]=Array.isArray(state._meta.usedFolios[key])?state._meta.usedFolios[key]:[];
 const v=String(value);
 if(!state._meta.usedFolios[key].includes(v))state._meta.usedFolios[key].push(v);
}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
function render(){const view=state.view||'dashboard';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const back=document.querySelector('.back-global');if(back){back.style.display=view==='dashboard'?'none':'inline-flex';}const c=document.getElementById('content');c.className='content';({dashboard:dashboard,quote:()=>documentForm('quote',c),note:()=>documentForm('note',c),clients:clients,products:products,history:history,archive:archive,tools:tools,settings:settings,templates:templates}[view]||dashboard)(c);bindNavigation();closeSidebarMobile();window.scrollTo({top:0,behavior:'smooth'});} 
