function num(v){
 if(typeof v==='number') return Number.isFinite(v)?v:0;
 const s=String(v??'').trim().replace(/[$\s]/g,'').replace(/,/g,'');
 const n=Number(s);
 return Number.isFinite(n)?n:0;
}
function calc(d){
 const sub=(d.items||[]).reduce((sum,it)=>sum+normalizeNonNegative(it.qty,0)*normalizeNonNegative(it.price,0),0);
 const discount=Math.max(0,num(d.discount));
 const taxable=Math.max(0,sub-discount);
 const rate=normalizeIva(d.company?.iva ?? state.settings.iva ?? 16);
 const ivaAmount=d.applyIva===false?0:taxable*rate/100;
 return {sub,discount,iva:ivaAmount,total:taxable+ivaAmount};
}
function updateTotalsUI(){
 const d=state.editing;if(!d)return;
 const c=calc(d);
 document.getElementById('subTotal').textContent=money(c.sub);
 document.getElementById('ivaTotal').textContent=money(c.iva);
 const ivaRateLabel=document.getElementById('ivaRateLabel'); if(ivaRateLabel)ivaRateLabel.textContent=`${normalizeIva(d.company?.iva ?? state.settings.iva)}%`;
 const ivaRow=document.getElementById('ivaRow');
 if(ivaRow) ivaRow.style.display=d.applyIva===false?'none':'';
 document.getElementById('grandTotal').textContent=money(c.total);
 d.items.forEach((it,i)=>{const e=document.getElementById('line_'+i);if(e)e.textContent=money(num(it.qty)*num(it.price));});
}
