function subtotal(d){return calc(d).sub}
function iva(d){return calc(d).iva}
function total(d){return calc(d).total}
function saveDoc(){
 const d=state.editing;if(!d)return;
 normalizeDocument(d);
 d.total=total(d);
 const idx=state.documents.findIndex(x=>x.id===d.id);
 touchRecord(d);
 state._meta.deleted.documents=(state._meta.deleted.documents||[]).filter(id=>id!==String(d.id));
 if(idx>=0){
 state.documents[idx]=JSON.parse(JSON.stringify(d));
 }else{
 d.id=makeId('doc');
 touchRecord(d);
 state.documents.push(JSON.parse(JSON.stringify(d)));
 }
 registerFolio(d.type,d.folio);
 save();
 state.editing=JSON.parse(JSON.stringify(d));
 toast('Documento guardado correctamente');
}
function editDoc(id){const d=state.documents.find(x=>x.id===id);if(d){state.editing=JSON.parse(JSON.stringify(d));if(!state.editing.status)state.editing.status='Pendiente';state.view=d.type;render()}}
function duplicateDoc(id){const src=state.documents.find(x=>x.id===id)||state.editing;if(!src)return toast('No hay documento para duplicar');const d=JSON.parse(JSON.stringify(src));d.id=null;d.folio=folio(d.type);const dates=documentDates(d.type,today());d.date=dates.dateStart;d.dateStart=dates.dateStart;d.dateEnd=dates.dateEnd;d.status='Pendiente';d.total=total(d);state.editing=d;state.view=d.type;render();toast('Documento duplicado. Revisa los datos y guárdalo.')}
function deleteDoc(id){
 const d=state.documents.find(x=>x.id===id);if(!d)return;
 const label=d.folio||'este documento';
 if(!confirm(`¿Deseas eliminar ${label}?\n\nEsta acción no se puede deshacer.`))return;
 registerFolio(d.type,d.folio);
 state.documents=state.documents.filter(x=>x.id!==id);
 state._meta.deleted.documents=Array.from(new Set([...(state._meta.deleted.documents||[]),String(id)]));
 state._meta.updatedAt=new Date().toISOString();
 if(state.editing?.id===id)state.editing=null;
 save();render();toast('Documento eliminado correctamente');
}
function deleteClient(i){const x=state.clients[Number(i)];if(!x)return;if(!confirm(`¿Deseas eliminar al cliente "${x.name||'este cliente'}"?\n\nEsta acción no se puede deshacer.`))return;const removedId=String(x.id||'');state.clients.splice(Number(i),1);state._meta.deleted.clients=Array.from(new Set([...(state._meta.deleted.clients||[]),removedId]));state._meta.updatedAt=new Date().toISOString();save();renderClientList(document.getElementById('clientListSearch')?.value||'');toast('Cliente eliminado correctamente.')}
function deleteProduct(i){const x=state.products[Number(i)];if(!x)return;if(!confirm(`¿Deseas eliminar el producto "${x.name||'este producto'}"?\n\nEsta acción no se puede deshacer.`))return;const removedId=String(x.id||'');state.products.splice(Number(i),1);state._meta.deleted.products=Array.from(new Set([...(state._meta.deleted.products||[]),removedId]));state._meta.updatedAt=new Date().toISOString();save();renderProductCatalog();toast('Producto eliminado correctamente.')}
function deleteToolList(id){const x=state.toolLists.find(z=>z.id===id);if(!x)return;if(!confirm(`¿Deseas eliminar la lista "${x.name||'Lista de herramientas'}"?\n\nEsta acción no se puede deshacer.`))return;state.toolLists=state.toolLists.filter(z=>z.id!==id);state._meta.deleted.toolLists=Array.from(new Set([...(state._meta.deleted.toolLists||[]),String(id)]));state._meta.updatedAt=new Date().toISOString();if(state.toolEditing?.id===id)state.toolEditing=null;save();render();toast('Lista eliminada correctamente.')}



