 if(!images.length)return toast('No hay imágenes adjuntadas en esta lista.');
 images.forEach((im,i)=>setTimeout(()=>{const a=document.createElement('a');a.href=im.data;a.download=im.name;document.body.appendChild(a);a.click();a.remove();},i*180));
