function toggleSecondaryBankFields(show){
 const card=document.getElementById('secondaryBankCard'),btn=document.getElementById('addSecondaryBankBtn'),flag=document.getElementById('s_secondaryBankEnabled');
 if(flag)flag.value=show?'1':'0';
 state.settings.secondaryBankEnabled=!!show;
 if(card)card.classList.toggle('hidden-bank',!show);
 if(btn)btn.classList.toggle('hidden-bank',show);
 if(!show){
 state.settings.bank2='';state.settings.holder2='';state.settings.account2='';state.settings.card2='';
 }else{
 const first=document.getElementById('s_bank2');if(first)first.focus();
 }
}

function saveSettings(){
 state.settings={...DEFAULT_SETTINGS,...state.settings};
 Object.keys(state.settings).forEach(k=>{
 if(k==='secondaryBankEnabled')return;
 const e=document.getElementById('s_'+k);
 if(e)state.settings[k]=k==='iva'?normalizeIva(e.value):String(e.value??'').trim();
 });
 const flag=document.getElementById('s_secondaryBankEnabled');
 state.settings.secondaryBankEnabled=flag ? flag.value==='1' : Boolean(state.settings.secondaryBankEnabled);
 if(!state.settings.secondaryBankEnabled){
 state.settings.bank2='';state.settings.holder2='';state.settings.account2='';state.settings.card2='';
 }
 state._meta.settingsUpdatedAt=new Date().toISOString();
 normalizeStateData();save();render();toast('Configuración guardada')
}
function backup(){const data={version:APP_VERSION,meta:{...(state._meta||{}),cloudSyncPending:Boolean(state._meta?.cloudSyncPending)},settings:state.settings,clients:state.clients,products:state.products,documents:state.documents,toolLists:state.toolLists};const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='SK_House_Construction_respaldo.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function restore(file){
 if(!file)return;
 const r=new FileReader();
 r.onload=()=>{
 try{
 const x=JSON.parse(r.result);
 if(!validBackup(x))throw new Error('INVALID_STRUCTURE');
 const candidate={settings:x.settings,clients:x.clients,products:x.products,documents:x.documents,toolLists:x.toolLists,editing:null,view:'dashboard',_meta:{...(x.meta&&typeof x.meta==='object'?x.meta:{}),restoredAt:new Date().toISOString()}};
 Object.keys(state).forEach(k=>delete state[k]);
 Object.assign(state,candidate);
 normalizeStateData();
 const valid=Array.isArray(state.clients)&&Array.isArray(state.products)&&Array.isArray(state.documents)&&Array.isArray(state.toolLists)&&state.settings&&typeof state.settings==='object';
 if(!valid)throw new Error('NORMALIZATION_FAILED');
 if(!saveLocal())throw new Error('LOCAL_SAVE_FAILED');
 save();
 render();
 toast('Datos restaurados correctamente');
 }catch(e){
 console.error('Restore:',e);
 try{
 const previous=JSON.parse(localStorage.getItem(KEY)||'null');
 if(previous&&typeof previous==='object'){Object.keys(state).forEach(k=>delete state[k]);Object.assign(state,previous);normalizeStateData();}
 }catch(_e){}
 toast('El archivo no es válido o no pudo guardarse. Tus datos anteriores permanecen intactos.');
 }
 };
 r.onerror=()=>toast('No se pudo leer el archivo de respaldo.');
 r.readAsText(file);
}

function esc(s){return String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]))}
function escMultiline(s){return esc(s).replace(/\r\n|\r|\n/g,'<br>')}
async function downloadDocumentImages(d){
 if(!d){toast('No hay documento para descargar.');return false}
 try{
 if(!window.html2canvas)throw new Error('CAPTURADOR_NO_DISPONIBLE');

 let paper=document.getElementById('paper'),temporary=false;
 if(!paper){
 paper=document.createElement('div');
 paper.innerHTML=docHTML(d);
 paper.style.cssText='position:absolute;left:0;top:0;width:794px;min-height:1123px;background:#fff;padding:0;font-family:Arial;color:#111;visibility:visible;opacity:1;pointer-events:none;z-index:2147483646';
 document.body.appendChild(paper);temporary=true;
 }

 try{
 const target=paper.matches('.preview-paper')
 ? (paper.querySelector(':scope > .preview-paper')||paper)
 : (paper.querySelector('.preview-paper')||paper);

 for(const img of [...target.querySelectorAll('img')]){
 try{
 if(!img.complete)await new Promise(resolve=>{img.onload=img.onerror=resolve});
 if(img.naturalWidth>0 && !String(img.src).startsWith('data:')){
 const cv=document.createElement('canvas');
 cv.width=img.naturalWidth;cv.height=img.naturalHeight;
 cv.getContext('2d').drawImage(img,0,0);
 img.src=cv.toDataURL('image/png');
 }
 }catch(e){}
 }

 if(document.fonts?.ready)await document.fonts.ready;
 await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));

 // Compacta únicamente la salida PDF para que la nota no empuje
 // los datos bancarios y totales fuera del área visible. La vista
 // normal de la aplicación conserva exactamente su diseño actual.
 target.classList.add('pdf-compact');

 const rect=target.getBoundingClientRect();
 const width=Math.max(1,Math.ceil(target.scrollWidth||rect.width||794));
 const height=Math.max(1,Math.ceil(target.scrollHeight||rect.height||1123));

 const canvas=await window.html2canvas(target,{
 width,height,scale:1.75,
 backgroundColor:'#fff',
 useCORS:false,allowTaint:false,
 imageTimeout:20000,logging:false,
 foreignObjectRendering:false,
 scrollX:0,scrollY:0,x:0,y:0
 });

 if(!canvas?.width||!canvas?.height)throw new Error('Imagen del documento vacía');

 const data=canvas.toDataURL('image/jpeg',0.90);
 if(!data||data.length<1000)throw new Error('JPG inválido');

 const safe=String(d.folio||'documento').replace(/[\\/:*?"<>|]/g,'_');
 const a=document.createElement('a');
 a.href=data;
 a.download=`${safe}_SK_House_Construction.jpg`;
 a.style.display='none';
 document.body.appendChild(a);
 a.click();
 setTimeout(()=>a.remove(),1000);
 toast('Cotización descargada en JPG.');
 return true;
 }finally{
 const target=paper?.matches?.('.preview-paper')
 ? (paper.querySelector(':scope > .preview-paper')||paper)
 : (paper?.querySelector?.('.preview-paper')||paper);
 if(target?.classList)target.classList.remove('pdf-compact');
 if(temporary)paper.remove();
 }
 }catch(e){
 console.error('Error generando JPG:',e);
 toast('No se pudo generar la cotización en JPG.');
 return false;
 }
}
function printDocumentOnly(d){
 if(!d)return toast('No hay documento para imprimir.');
 showPreview(d);
 setTimeout(()=>window.print(),120);
}
