 const addImage=(data,type,x,yy,w,h,key)=>{
 if(!data) throw new Error('IMAGE_DATA_MISSING');
 try{pdf.addImage(data,type,sx(x),sy(yy),sw(w),sw(h),key,'FAST');return true}
 catch(e){throw new Error('PDF_IMAGE_FAILED:'+String(e?.message||e))}
 };
