 const nameVal=String(client.name||'').trim(), phoneVal=String(client.phone||'').trim(), emailVal=String(client.email||'').trim(), rfcVal=String(client.rfc||'').trim(), addressVal=String(client.address||'').trim();
 const contact=[['Teléfono',phoneVal],['Correo electrónico',emailVal],['RFC',rfcVal]].filter(x=>x[1]);
