 if(nameVal){addText('NOMBRE / RAZÓN SOCIAL',M+4,cy,5.1,'bold',gray);nameLines.forEach((t,j)=>addRichText(t,M+4,cy+3+j*clientLineH,6.8,'normal',[29,45,66],{maxWidth:CW-8}));cy+=clientLabelH+Math.max(1,nameLines.length)*clientLineH+clientGap;}
 contact.forEach((f,idx)=>{addText(f[0].toUpperCase(),M+4,cy,5.1,'bold',gray);contactLines[idx].forEach((t,j)=>addRichText(t,M+4,cy+3+j*clientLineH,6.2,'normal',[29,45,66],{maxWidth:CW-8}));cy+=clientLabelH+Math.max(1,contactLines[idx].length)*clientLineH+clientGap;});
 if(addressVal){addText('DIRECCIÓN',M+4,cy,5.1,'bold',gray);addressLines.forEach((t,j)=>addRichText(t,M+4,cy+3+j*clientLineH,6.5,'normal',[29,45,66],{maxWidth:CW-8}));}
