async function downloadPDF(d){
 if(!d){toast('No hay documento para guardar.');return false}
 try{
 const blob=await buildPDFBlob(d);
 const safe=String(d.folio||'documento').replace(/[\\/:*?"<>|]/g,'_');
 const url=URL.createObjectURL(blob);
 const a=document.createElement('a');
 a.href=url;a.download=`${safe}_SK_House_Construction.pdf`;a.style.display='none';
 document.body.appendChild(a);a.click();
 setTimeout(()=>{try{URL.revokeObjectURL(url);a.remove()}catch(e){}},30000);
 toast('PDF generado correctamente.'); return true;
 }catch(e){
 console.error('Error generando PDF:',e);
 toast(e?.message==='PDF_LIBRARIES_UNAVAILABLE'?'No se pudo cargar el generador PDF. Conéctate a Internet una vez y vuelve a intentarlo.':e?.message==='PDF_CAPTURE_LIBRARY_UNAVAILABLE'?'No se pudo cargar el capturador del PDF. Conéctate a Internet una vez y vuelve a intentarlo.':'No se pudo generar el PDF. Inténtalo nuevamente.');
 return false;
 }
}

function shareMessage(d){
 const tipo=d.type==='quote'?'cotización':'nota de venta';
 const cliente=(d.client?.name||'cliente').trim();
 const concepto=(d.items||[]).map(x=>String(x.desc||'').trim()).filter(Boolean)[0]||'';
 const detalle=concepto?` correspondiente a ${concepto}`:'';
 return `Hola ${cliente},\n\nTe compartimos tu ${tipo} ${d.folio}${detalle}, elaborada por SK House Construction.\n\nAdjuntamos el documento en PDF para tu revisión. Si tienes alguna pregunta o deseas realizar algún ajuste, con gusto te atenderemos.\n\nSaludos cordiales,\nSK House Construction`;
}

function normalizeMexicoPhone(phone){
 let clean=String(phone||'').replace(/\D/g,'');
 if(clean.startsWith('00'))clean=clean.slice(2);
 if(clean.startsWith('52')&&clean.length===12)return clean;
 if(clean.length===10)return '52'+clean;
 return clean;
}
function whatsappUrl(message,phone=''){
 const clean=normalizeMexicoPhone(phone);
 return clean
 ? `https://wa.me/${clean}?text=${encodeURIComponent(message)}`
 : `https://wa.me/?text=${encodeURIComponent(message)}`;
}
function openWhatsApp(message,phone=''){
 const url=whatsappUrl(message,phone);
 const a=document.createElement('a');
 a.href=url;a.target='_blank';a.rel='noopener';
 document.body.appendChild(a);a.click();a.remove();
 setTimeout(()=>{if(document.visibilityState==='visible' && !document.hidden){/* popup may have been blocked */}},400);
 return url;
}
function emailUrl(email,subject,body){
 const to=String(email||'').trim();
 return 'mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
}
function openEmail(email,subject,body){
 const url=emailUrl(email,subject,body);
 window.location.href=url;
 return url;
}

async function shareDoc(d){
 if(!d){toast('No hay documento para compartir.');return false}
 const message=shareMessage(d);
 const docName=d.type==='quote'?'Cotización':'Nota de venta';
 const safe=String(d.folio||'documento').replace(/[\\/:*?"<>|]/g,'_');
 const filename=`${safe}_SK_House_Construction.pdf`;

 // Primero generamos UNA sola vez el PDF. En dispositivos compatibles con
 // Web Share se entrega el archivo real a la aplicación elegida.
 let blob;
 try{
 blob=await buildPDFBlob(d);
 if(!(blob instanceof Blob)||blob.size<5000)throw new Error('PDF_EMPTY_OUTPUT');
 }catch(e){
 console.error('Error preparando PDF para compartir:',e);
 toast(e?.message==='PDF_LIBRARIES_UNAVAILABLE'?'No se pudo cargar el generador PDF. Conéctate a Internet una vez y vuelve a intentarlo.':'No se pudo generar el PDF para compartir.');
 return false;
 }

 try{
 if(typeof navigator.share==='function'){
 const file=new File([blob],filename,{type:'application/pdf'});
 let fileShare=false;
 try{fileShare=typeof navigator.canShare==='function' && navigator.canShare({files:[file]});}catch(e){fileShare=false}
 if(fileShare){
 await navigator.share({title:`${docName} ${d.folio}`,text:message,files:[file]});
 return true;
 }
 }
 }catch(e){
 if(e?.name==='AbortError')return false;
 console.warn('Web Share:',e);
 }

 // Escritorio/WhatsApp Web: el navegador no permite adjuntar un archivo local
 // automáticamente a una ventana de WhatsApp Web. Descargamos EL MISMO Blob
 // que acabamos de generar y después abrimos WhatsApp con el mensaje listo.
 try{
 const url=URL.createObjectURL(blob);
 const a=document.createElement('a');
 a.href=url;a.download=filename;a.style.display='none';
 document.body.appendChild(a);a.click();
 setTimeout(()=>{try{a.remove();URL.revokeObjectURL(url)}catch(e){}},30000);
 openWhatsApp(message,d.client?.phone||'');
 toast('PDF descargado. Adjunta ese archivo en WhatsApp.');
 return true;
 }catch(e){
 console.error('Error descargando PDF para WhatsApp:',e);
 toast('No se pudo descargar el PDF para compartir.');
 return false;
 }
}
async function shareByEmail(d){
 if(!d){toast('No hay documento para enviar.');return false}
 const subject=`${d.type==='quote'?'Cotización':'Nota de venta'} ${d.folio} - SK House Construction`;
 const body=shareMessage(d);
 const email=String(d.client?.email||'').trim();
 if(!email)return toast('El cliente no tiene un correo electrónico registrado.');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('El correo del cliente no tiene un formato válido.');
 const safe=String(d.folio||'documento').replace(/[\\/:*?"<>|]/g,'_');
 const filename=`${safe}_SK_House_Construction.pdf`;
 let blob;
 try{
 // Build exactly one verified PDF. Never pass a malformed/empty Blob to a mail app.
 blob=await buildPDFBlob(d);
 if(!(blob instanceof Blob) || blob.type!=='application/pdf' || blob.size<5000) throw new Error('PDF_INVALID_FOR_EMAIL');
 }catch(e){
 console.error('PDF para correo:',e);
 toast('No se pudo crear un PDF válido para el correo.');
 return false;
 }
 const file=new File([blob],filename,{type:'application/pdf',lastModified:Date.now()});
 // The only browser API capable of handing a real attachment to a mail app is Web Share.
 // Use it only when the browser explicitly confirms that this exact File is shareable.
 try{
 if(typeof navigator.share==='function' && typeof navigator.canShare==='function'){
 let canShareFile=false;
 try{ canShareFile=navigator.canShare({files:[file]})===true; }catch(_e){ canShareFile=false; }
 if(canShareFile){
 await navigator.share({title:subject,text:body,files:[file]});
 toast('Correo abierto con el PDF adjunto.');
 return true;
 }
 }
 }catch(e){
 if(e?.name==='AbortError') return false;
 console.warn('Web Share rechazó el PDF:',e);
 }
 // Desktop/webmail cannot be given an attachment programmatically by mailto().
 // Save the verified PDF and open the message composer. No fake attachment parameter is used.
 try{
 const url=URL.createObjectURL(blob);
 const a=document.createElement('a');
 a.href=url;a.download=filename;a.style.display='none';
 document.body.appendChild(a);a.click();
 setTimeout(()=>{try{a.remove();URL.revokeObjectURL(url)}catch(_e){}},60000);
 const mailUrl=emailUrl(email,subject,body);
 // Use an anchor click rather than replacing the SPA location.
 const mail=document.createElement('a');
 mail.href=mailUrl;mail.style.display='none';
 document.body.appendChild(mail);mail.click();mail.remove();
 toast('PDF guardado. Adjunta el archivo que se acaba de descargar al correo.');
 return true;
 }catch(e){
 console.error('Preparando correo:',e);
 toast('No se pudo preparar el correo.');
 return false;
 }
}

