// Recover the persisted Supabase session without relying on a fixed startup delay.
let cloudStartupPromise=null;
async function initializeCloudSession(){
 if(cloudStartupPromise)return cloudStartupPromise;
 cloudStartupPromise=(async()=>{
 if(!window.SKCloud)return;
 try{
 const user=await window.SKCloud.session();
 if(user){
 await syncCloudIntoState();
 clearInterval(window.SKCloudSyncTimer);
 window.SKCloudSyncTimer=setInterval(backgroundCloudSync,30000);
 }else{
 cloudSyncReady=false;
 await updateCloudStatus();
 }
 }catch(e){
 cloudSyncReady=false;
 console.warn('Cloud startup:',e);
 await updateCloudStatus();
 }finally{
 cloudStartupPromise=null;
 }
 })();
 return cloudStartupPromise;
}
