 const decimalParts=raw.split(/\s+(?:punto|con)\s+/);
 const integerWords=decimalParts[0];
 const words=integerWords.replace(/[-]/g,' ').split(/\s+/).filter(Boolean);
 let total=0,current=0,has=false;
